/** Deno/Node can compile embedded bytes; no deployment-time static asset is needed. */
export function createArgon2Module(): WebAssembly.Module {
  const bytes = Uint8Array.from(atob(encoded), (character) => character.charCodeAt(0));
  return new WebAssembly.Module(bytes);
}
